import{_ as s,o as i,c as a,ah as r}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Caisse","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/caissier/index.md","filePath":"src/guide/caissier/index.md"}'),t={name:"guide/caissier/index.md"};function n(o,e,l,u,c,d){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="caisse" tabindex="-1">Caisse <a class="header-anchor" href="#caisse" aria-label="Permalink to &quot;Caisse&quot;">​</a></h1><p>La caisse gère l&#39;inscription financière des élèves une fois leur dossier validé par le secrétariat : les frais dus, les paiements encaissés, les remises accordées et les échéanciers de paiement. Elle suit aussi les dépenses de l&#39;établissement et produit les exports comptables. Le menu de gauche vous donne accès à trois pages :</p><ul><li><strong><a href="/era-guide/guide/caissier/inscriptions-et-paiements.html">Inscriptions et paiements</a></strong> — saisir un nouveau dossier pour une famille présente sur site, suivre les frais dus par élève, encaisser un paiement, imprimer un reçu, mettre en place un échéancier et consulter les remises accordées.</li><li><strong><a href="/era-guide/guide/caissier/export-comptable.html">Export comptable</a></strong> — exporter les paiements et les dépenses au format CSV, SYSCOHADA, ou sous forme de relevé par classe.</li><li><strong><a href="/era-guide/guide/caissier/depenses.html">Dépenses</a></strong> — enregistrer une dépense de l&#39;établissement et suivre son état.</li></ul><p>Pour comprendre comment un élève arrive jusqu&#39;à la caisse, voir le <a href="/era-guide/guide/secretariat/">guide du secrétariat</a> — c&#39;est la validation d&#39;un dossier de candidature qui crée l&#39;inscription financière que vous retrouvez ensuite dans <strong>Facturation</strong>.</p>',4)])])}const g=s(t,[["render",n]]);export{m as __pageData,g as default};
